package com.machinefault.api.api;
import com.machinefault.api.api.ApiModels.*; import com.machinefault.api.domain.Machine; import com.machinefault.api.domain.MachineStatus; import com.machinefault.api.repo.MachineRepository; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
// Routes for listing active machines and adding a machine as an administrator.
@RestController @RequestMapping("/api/machines") public class MachineController {
 private final MachineRepository machines; public MachineController(MachineRepository m){machines=m;}
 @GetMapping public List<MachineView> list(){return machines.findByActiveTrue().stream().map(MachineView::of).toList();}
 @GetMapping("/{id}") public MachineView get(@PathVariable Long id){return MachineView.of(machines.findById(id).filter(Machine::isActive).orElseThrow(()->new NoSuchElementException("Machine not found.")));}
 @PostMapping @PreAuthorize("hasAuthority('SYSTEM_ADMINISTRATOR')") public ResponseEntity<MachineView> create(@Valid @RequestBody CreateMachine body){if(machines.findByIdentifierAndActiveTrue(body.identifier()).isPresent())throw new IllegalArgumentException("Machine identifier already exists.");Machine machine=new Machine(body.identifier(),body.name(),body.location());machine.setStatus(body.status()==null?MachineStatus.OPERATIONAL:body.status());return ResponseEntity.status(201).body(MachineView.of(machines.save(machine)));}
 @PutMapping("/{id}") @PreAuthorize("hasAuthority('SYSTEM_ADMINISTRATOR')") public MachineView update(@PathVariable Long id,@Valid @RequestBody UpdateMachine body){Machine machine=machines.findById(id).filter(Machine::isActive).orElseThrow(()->new NoSuchElementException("Machine not found."));machines.findByIdentifierAndActiveTrue(body.identifier()).filter(other->!other.getId().equals(id)).ifPresent(other->{throw new IllegalArgumentException("Machine identifier already exists.");});machine.update(body.identifier(),body.name(),body.location(),body.status());return MachineView.of(machines.save(machine));}
 @DeleteMapping("/{id}") @PreAuthorize("hasAuthority('SYSTEM_ADMINISTRATOR')") public ResponseEntity<Void> delete(@PathVariable Long id){Machine machine=machines.findById(id).orElseThrow(()->new NoSuchElementException("Machine not found."));machine.deactivate();machines.save(machine);return ResponseEntity.noContent().build();}
}
